export type ReceiptActor = 'user' | 'rob' | string; // engine names allowed
export type ReceiptOutcome = 'success' | 'blocked' | 'error' | 'unknown';
export type TruthState = 'Verified' | 'Unknown';

export interface Receipt {
  receipt_id: string;
  session_id: string;
  timestamp: string;
  actor: ReceiptActor;
  action_type: string;
  outcome: ReceiptOutcome;
  evidence_refs: string[];
  truth_state: TruthState;
  metadata?: Record<string, unknown>;
  parent_receipt_id?: string; // For tracing causal chains
}

export interface EngineInvocationReceipt extends Receipt {
  action_type: 'engine_invoked';
  metadata: {
    engine_name: string;
    input_hash?: string;
    output_hash?: string;
    duration_ms: number;
  };
}

export interface GateCheckReceipt extends Receipt {
  action_type: 'gate_checked';
  metadata: {
    gate_type: 'config' | 'paywall' | 'charter';
    gate_key: string;
    allowed: boolean;
    reason?: string;
  };
}

export class ReceiptSystem {
  private receipts: Map<string, Receipt> = new Map();
  private receiptsBySession: Map<string, Receipt[]> = new Map();

  /**
   * Emit a receipt (immutable once created)
   */
  emit(receipt: Omit<Receipt, 'receipt_id' | 'timestamp'>): Receipt {
    const fullReceipt: Receipt = {
      ...receipt,
      receipt_id: this.generateReceiptId(),
      timestamp: new Date().toISOString(),
    };

    this.receipts.set(fullReceipt.receipt_id, fullReceipt);

    // Index by session
    if (!this.receiptsBySession.has(fullReceipt.session_id)) {
      this.receiptsBySession.set(fullReceipt.session_id, []);
    }
    this.receiptsBySession.get(fullReceipt.session_id)!.push(fullReceipt);

    return fullReceipt;
  }

  /**
   * Emit session created receipt
   */
  emitSessionCreated(sessionId: string, appName: string, goals: string[]): Receipt {
    return this.emit({
      session_id: sessionId,
      actor: 'user',
      action_type: 'session_created',
      outcome: 'success',
      evidence_refs: [],
      truth_state: 'Verified',
      metadata: { appName, goals },
    });
  }

  /**
   * Emit user input received
   */
  emitUserInput(sessionId: string, input: unknown): Receipt {
    return this.emit({
      session_id: sessionId,
      actor: 'user',
      action_type: 'user_input_received',
      outcome: 'success',
      evidence_refs: [],
      truth_state: 'Verified',
      metadata: { input },
    });
  }

  /**
   * Emit engine invocation
   */
  emitEngineInvoked(
    sessionId: string,
    engineName: string,
    durationMs: number,
    outcome: ReceiptOutcome,
    parentReceiptId?: string
  ): EngineInvocationReceipt {
    return this.emit({
      session_id: sessionId,
      actor: engineName,
      action_type: 'engine_invoked',
      outcome,
      evidence_refs: [],
      truth_state: outcome === 'success' ? 'Verified' : 'Unknown',
      metadata: {
        engine_name: engineName,
        duration_ms: durationMs,
      },
      parent_receipt_id: parentReceiptId,
    }) as EngineInvocationReceipt;
  }

  /**
   * Emit gate check (config/paywall/charter)
   */
  emitGateCheck(
    sessionId: string,
    gateType: 'config' | 'paywall' | 'charter',
    gateKey: string,
    allowed: boolean,
    reason?: string,
    parentReceiptId?: string
  ): GateCheckReceipt {
    return this.emit({
      session_id: sessionId,
      actor: gateType + 'Engine',
      action_type: 'gate_checked',
      outcome: allowed ? 'success' : 'blocked',
      evidence_refs: [],
      truth_state: 'Verified',
      metadata: {
        gate_type: gateType,
        gate_key: gateKey,
        allowed,
        reason,
      },
      parent_receipt_id: parentReceiptId,
    }) as GateCheckReceipt;
  }

  /**
   * Emit action executed
   */
  emitActionExecuted(
    sessionId: string,
    actor: ReceiptActor,
    action: string,
    outcome: ReceiptOutcome,
    evidenceRefs: string[],
    parentReceiptId?: string
  ): Receipt {
    return this.emit({
      session_id: sessionId,
      actor,
      action_type: 'action_executed',
      outcome,
      evidence_refs: evidenceRefs,
      truth_state: outcome === 'success' ? 'Verified' : 'Unknown',
      metadata: { action },
      parent_receipt_id: parentReceiptId,
    });
  }

  /**
   * Get all receipts for a session
   */
  getReceiptsForSession(sessionId: string): Receipt[] {
    return this.receiptsBySession.get(sessionId) || [];
  }

  /**
   * Get receipt by ID
   */
  getReceipt(receiptId: string): Receipt | undefined {
    return this.receipts.get(receiptId);
  }

  /**
   * Get receipt chain (follow parent_receipt_id)
   */
  getReceiptChain(receiptId: string): Receipt[] {
    const chain: Receipt[] = [];
    let current = this.getReceipt(receiptId);

    while (current) {
      chain.push(current);
      if (current.parent_receipt_id) {
        current = this.getReceipt(current.parent_receipt_id);
      } else {
        break;
      }
    }

    return chain.reverse(); // Return root-to-leaf
  }

  /**
   * Validate session receipts for completeness
   */
  validateSession(sessionId: string): {
    valid: boolean;
    issues: string[];
    receipts: Receipt[];
  } {
    const receipts = this.getReceiptsForSession(sessionId);
    const issues: string[] = [];

    if (receipts.length === 0) {
      issues.push('No receipts found for session');
    }

    // Check for session_created
    if (!receipts.some((r) => r.action_type === 'session_created')) {
      issues.push('Missing session_created receipt');
    }

    // Check for Unknown truth states
    const unknowns = receipts.filter((r) => r.truth_state === 'Unknown');
    if (unknowns.length > 0) {
      issues.push(`${unknowns.length} receipts have Unknown truth state`);
    }

    // Check for blocked or error outcomes
    const blocked = receipts.filter((r) => r.outcome === 'blocked' || r.outcome === 'error');
    if (blocked.length > 0) {
      issues.push(`${blocked.length} receipts show blocked/error outcomes`);
    }

    return {
      valid: issues.length === 0,
      issues,
      receipts,
    };
  }

  private generateReceiptId(): string {
    return `receipt_${Date.now()}_${Math.random().toString(36).slice(2, 11)}`;
  }
}

/**
 * TruthSerumValidator™ - Investor-Grade Proof Mechanism
 * 
 * VALIDATES:
 * - Engine awareness (who talks to who)
 * - Coordination proofs (receipts)
 * - Ordering enforcement
 * - No false claims
 */

import type { Receipt } from './ReceiptSystem';

export interface EngineInteraction {
  from: string;
  to: string;
  evidence: string; // receipt ID
  verified: boolean;
}

export interface EngineAwarenessMatrix {
  engines: string[];
  interactions: EngineInteraction[];
}

export interface TruthSerumReport {
  sessionId: string;
  valid: boolean;
  engineAwarenessMatrix: EngineAwarenessMatrix;
  orderingViolations: string[];
  missingReceipts: string[];
  unverifiedClaims: string[];
  summary: {
    enginesInvoked: string[];
    gatesChecked: string[];
    totalReceipts: number;
    verifiedReceipts: number;
    unknownReceipts: number;
  };
}

export class TruthSerumValidator {
  /**
   * Audit a session's receipts for TruthSerum compliance
   */
  validate(sessionId: string, receipts: Receipt[]): TruthSerumReport {
    const orderingViolations: string[] = [];
    const missingReceipts: string[] = [];
    const unverifiedClaims: string[] = [];
    const enginesInvoked: Set<string> = new Set();
    const gatesChecked: Set<string> = new Set();
    const interactions: EngineInteraction[] = [];

    // Track receipt chain
    const receiptMap = new Map<string, Receipt>();
    receipts.forEach((r) => receiptMap.set(r.receipt_id, r));

    // Validate each receipt
    for (const receipt of receipts) {
      // Track engines
      if (receipt.action_type === 'engine_invoked') {
        const engineName = (receipt.metadata as any)?.engine_name || receipt.actor;
        enginesInvoked.add(engineName);

        // Build interaction chain
        if (receipt.parent_receipt_id) {
          const parent = receiptMap.get(receipt.parent_receipt_id);
          if (parent) {
            const fromEngine = this.extractEngine(parent);
            const toEngine = engineName;
            interactions.push({
              from: fromEngine,
              to: toEngine,
              evidence: receipt.receipt_id,
              verified: receipt.truth_state === 'Verified',
            });
          }
        }
      }

      // Track gates
      if (receipt.action_type === 'gate_checked') {
        const gateType = (receipt.metadata as any)?.gate_type;
        if (gateType) {
          gatesChecked.add(gateType);
        }
      }

      // Check for Unknown truth state
      if (receipt.truth_state === 'Unknown') {
        unverifiedClaims.push(
          `Receipt ${receipt.receipt_id}: ${receipt.action_type} has Unknown truth state`
        );
      }

      // Check for missing parent receipts
      if (receipt.parent_receipt_id && !receiptMap.has(receipt.parent_receipt_id)) {
        missingReceipts.push(
          `Receipt ${receipt.receipt_id} references missing parent ${receipt.parent_receipt_id}`
        );
      }
    }

    // Validate canonical ordering (if AI invocation exists)
    const hasAI = receipts.some(
      (r) =>
        r.action_type === 'engine_invoked' &&
        (r.metadata as any)?.engine_name === 'SilentEngine'
    );

    if (hasAI) {
      orderingViolations.push(...this.validateAIFlowOrdering(receipts));
    }

    // Build awareness matrix
    const engineAwarenessMatrix: EngineAwarenessMatrix = {
      engines: Array.from(enginesInvoked),
      interactions,
    };

    // Calculate summary
    const verifiedReceipts = receipts.filter((r) => r.truth_state === 'Verified').length;
    const unknownReceipts = receipts.filter((r) => r.truth_state === 'Unknown').length;

    const valid =
      orderingViolations.length === 0 &&
      missingReceipts.length === 0 &&
      unverifiedClaims.length === 0;

    return {
      sessionId,
      valid,
      engineAwarenessMatrix,
      orderingViolations,
      missingReceipts,
      unverifiedClaims,
      summary: {
        enginesInvoked: Array.from(enginesInvoked),
        gatesChecked: Array.from(gatesChecked),
        totalReceipts: receipts.length,
        verifiedReceipts,
        unknownReceipts,
      },
    };
  }

  /**
   * Validate canonical AI flow ordering:
   * 1. Identity
   * 2. Charter (consent)
   * 3. Config (gate)
   * 4. Paywall (entitlement)
   * 5. SilentEngine (AI)
   */
  private validateAIFlowOrdering(receipts: Receipt[]): string[] {
    const violations: string[] = [];
    const orderedEngines = ['IdentityEngine', 'charterEngine', 'configEngine', 'paywallEngine', 'SilentEngine'];

    // Find timestamps of each engine invocation
    const engineTimestamps = new Map<string, number>();

    for (const receipt of receipts) {
      if (receipt.action_type === 'engine_invoked') {
        const engineName = (receipt.metadata as any)?.engine_name || receipt.actor;
        const timestamp = new Date(receipt.timestamp).getTime();

        if (!engineTimestamps.has(engineName)) {
          engineTimestamps.set(engineName, timestamp);
        }
      } else if (receipt.action_type === 'gate_checked') {
        const gateType = (receipt.metadata as any)?.gate_type;
        const engineName = gateType ? gateType + 'Engine' : receipt.actor;
        const timestamp = new Date(receipt.timestamp).getTime();

        if (!engineTimestamps.has(engineName)) {
          engineTimestamps.set(engineName, timestamp);
        }
      }
    }

    // Check ordering
    let lastTimestamp = 0;
    for (const engineName of orderedEngines) {
      const timestamp = engineTimestamps.get(engineName);
      if (timestamp !== undefined) {
        if (timestamp < lastTimestamp) {
          violations.push(
            `Ordering violation: ${engineName} ran at ${new Date(timestamp).toISOString()} before expected sequence`
          );
        }
        lastTimestamp = timestamp;
      }
    }

    // Ensure SilentEngine ran AFTER all gates
    const silentTimestamp = engineTimestamps.get('SilentEngine');
    if (silentTimestamp) {
      for (const [engine, timestamp] of engineTimestamps.entries()) {
        if (
          ['charterEngine', 'configEngine', 'paywallEngine'].includes(engine) &&
          timestamp > silentTimestamp
        ) {
          violations.push(
            `Gate ${engine} ran AFTER SilentEngine - gates must run BEFORE action`
          );
        }
      }
    }

    return violations;
  }

  private extractEngine(receipt: Receipt): string {
    if (receipt.action_type === 'engine_invoked') {
      return (receipt.metadata as any)?.engine_name || receipt.actor;
    }
    if (receipt.action_type === 'gate_checked') {
      const gateType = (receipt.metadata as any)?.gate_type;
      return gateType ? gateType + 'Engine' : receipt.actor;
    }
    return receipt.actor;
  }

  /**
   * Generate human-readable report
   */
  generateReport(report: TruthSerumReport): string {
    const lines: string[] = [];

    lines.push('═══════════════════════════════════════════════');
    lines.push('TRUTHSERUM VALIDATION REPORT');
    lines.push('═══════════════════════════════════════════════');
    lines.push('');
    lines.push(`Session ID: ${report.sessionId}`);
    lines.push(`Status: ${report.valid ? '✅ VERIFIED' : '❌ INVALID'}`);
    lines.push('');

    lines.push('ENGINE AWARENESS MATRIX');
    lines.push('─────────────────────────────────────────────');
    if (report.engineAwarenessMatrix.interactions.length === 0) {
      lines.push('⚠️  No engine interactions detected');
    } else {
      for (const interaction of report.engineAwarenessMatrix.interactions) {
        const status = interaction.verified ? '✅' : '❌';
        lines.push(`${status} ${interaction.from} → ${interaction.to}`);
        lines.push(`   Evidence: ${interaction.evidence}`);
      }
    }
    lines.push('');

    lines.push('SUMMARY');
    lines.push('─────────────────────────────────────────────');
    lines.push(`Engines Invoked: ${report.summary.enginesInvoked.join(', ') || 'None'}`);
    lines.push(`Gates Checked: ${report.summary.gatesChecked.join(', ') || 'None'}`);
    lines.push(`Total Receipts: ${report.summary.totalReceipts}`);
    lines.push(`Verified: ${report.summary.verifiedReceipts}`);
    lines.push(`Unknown: ${report.summary.unknownReceipts}`);
    lines.push('');

    if (report.orderingViolations.length > 0) {
      lines.push('⚠️  ORDERING VIOLATIONS');
      lines.push('─────────────────────────────────────────────');
      report.orderingViolations.forEach((v) => lines.push(`  • ${v}`));
      lines.push('');
    }

    if (report.missingReceipts.length > 0) {
      lines.push('⚠️  MISSING RECEIPTS');
      lines.push('─────────────────────────────────────────────');
      report.missingReceipts.forEach((m) => lines.push(`  • ${m}`));
      lines.push('');
    }

    if (report.unverifiedClaims.length > 0) {
      lines.push('⚠️  UNVERIFIED CLAIMS');
      lines.push('─────────────────────────────────────────────');
      report.unverifiedClaims.forEach((u) => lines.push(`  • ${u}`));
      lines.push('');
    }

    lines.push('═══════════════════════════════════════════════');

    return lines.join('\n');
  }
}

/**
 * Generate receipts for a completed build session
 */

import type { BuildSession, ReceiptsBundle } from '../types';

export function generateReceipts(session: BuildSession): ReceiptsBundle {
  const stepsRun = session.steps.map((step) => ({
    id: step.id,
    status: step.status,
    summary: step.result?.summary || step.explanation,
  }));

  const checksPassed = session.steps
    .filter((s) => s.actionType === 'check' && s.status === 'success')
    .map((s) => s.title);

  const checksFailed = session.steps
    .filter((s) => s.actionType === 'check' && s.status === 'error')
    .map((s) => s.title);

  return {
    appName: session.appName,
    sessionId: session.id,
    goals: session.goals,
    enginesTouched: session.enginesTouched,
    stepsRun,
    checksPassed,
    checksFailed,
    createdAt: session.createdAt,
    qbOSVersion: '3.0.0',
  };
}

/**
 * Receipts API - Read receipts for a session
 */

import { ReceiptWriter } from '@qbos/truthserum';
import { NextRequest, NextResponse } from 'next/server';

const receiptWriter = new ReceiptWriter({
  localFallbackPath: './proof/local_receipts.jsonl',
});

export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url);
    const sessionId = searchParams.get('sessionId') || undefined;
    const limit = parseInt(searchParams.get('limit') || '100');

    const receipts = await receiptWriter.readReceipts(sessionId);

    return NextResponse.json({
      receipts: receipts.slice(-limit),
      count: receipts.length,
      sessionId,
    });
  } catch (error) {
    console.error('Receipts read error:', error);
    return NextResponse.json(
      { error: 'Failed to read receipts' },
      { status: 500 }
    );
  }
}

export async function POST(request: NextRequest) {
  try {
    const receiptData = await request.json();

    // If incoming payload includes a signature, verify it before accepting.
    if (receiptData && receiptData.sig && receiptData.signerKeyId) {
      const ok = await receiptWriter.verifyReceipt(receiptData);
      if (!ok) {
        return NextResponse.json({ error: 'Invalid signature' }, { status: 400 });
      }
      // Accept already-signed receipts (append-only)
      const receipt = await receiptWriter.writeReceipt(receiptData);
      return NextResponse.json({ receipt, status: 'written' });
    }

    // For unsigned receipts, the writer will sign then write.
    const receipt = await receiptWriter.writeReceipt(receiptData);

    return NextResponse.json({
      receipt,
      status: 'written',
    });
  } catch (error) {
    console.error('Receipt write error:', error);
    return NextResponse.json(
      { error: 'Failed to write receipt' },
      { status: 500 }
    );
  }
}

import { IdentityEngine } from '@qbos/identity-engine-core';
import { NextRequest, NextResponse } from 'next/server';
import { ReceiptWriter } from '../../../../packages/truthserum/src/ReceiptWriter';

const ALLOWED_SERVER_SIGN_TYPES = [
  'build.session.created',
  'build.step.completed',
  'deployment.triggered',
  'template.applied',
  'generation.completed',
  'github.repo.created',
  'vercel.deployment.completed',
  'healthcheck.passed',
  'delegation.progressed',
  'delegation.reverted'
];

export async function POST(req: NextRequest) {
  try {
    const authHeader = req.headers.get('authorization');
    if (!authHeader?.startsWith('Bearer ')) {
      return NextResponse.json({ error: 'Missing Authorization header' }, { status: 401 });
    }

    const token = authHeader.substring(7);

    const identityEngine = new IdentityEngine();
    const session = await identityEngine.validateSession(token);

    if (!session || !session.userId) {
      return NextResponse.json({ error: 'Invalid or expired session token' }, { status: 401 });
    }

    const payload = await req.json();

    if (!payload?.type || !ALLOWED_SERVER_SIGN_TYPES.includes(payload.type)) {
      return NextResponse.json({ error: 'Unauthorized receipt type', allowedTypes: ALLOWED_SERVER_SIGN_TYPES }, { status: 403 });
    }

    const details = {
      ...payload.details,
      actor: {
        userId: session.userId,
        orgId: session.orgId || null,
        role: session.role || 'user'
      },
      serverSigned: true,
      ipAddress: req.headers.get('x-forwarded-for') || 'unknown',
      userAgent: req.headers.get('user-agent') || 'unknown'
    };

    const receipt = await ReceiptWriter.write({
      sessionId: session.id,
      type: payload.type,
      details
    });

    return NextResponse.json(receipt);
  } catch (error) {
    console.error('[Server-Sign] Error:', error);
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

import { createClient } from '@supabase/supabase-js';
import { NextRequest, NextResponse } from 'next/server';
import { ReceiptWriter } from '../../../../packages/truthserum/src/ReceiptWriter';

const supabase = createClient(process.env.NEXT_PUBLIC_SUPABASE_URL || '', process.env.SUPABASE_SERVICE_ROLE_KEY || '');

export async function POST(req: NextRequest) {
  try {
    const payload = await req.json();

    if (!payload || !payload.signature || !payload.signerKeyId) {
      return NextResponse.json({ error: 'Missing signature or signerKeyId' }, { status: 400 });
    }

    // Verify signature using ReceiptWriter helper (canonicalization + keystore)
    const valid = await ReceiptWriter.verifyReceipt(payload);

    if (!valid) {
      return NextResponse.json({ error: 'Invalid signature' }, { status: 400 });
    }

    // Persist receipt into build_receipts (append-only)
    const { data, error } = await supabase.from('build_receipts').insert([
      {
        session_id: payload.sessionId || null,
        type: payload.type || 'unknown',
        details: payload.details || {},
        signature: payload.signature,
        signer_key_id: payload.signerKeyId,
        verification_hash: payload.verification_hash || null,
        created_at: new Date().toISOString()
      }
    ]);

    if (error) {
      console.error('[submit-signed] supabase insert error', error);
      return NextResponse.json({ error: 'Failed to persist receipt' }, { status: 500 });
    }

    return NextResponse.json({ ok: true, inserted: data });
  } catch (err) {
    console.error('[submit-signed] Error:', err);
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

